public class Main {
    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    public static void main(String[] args) throws IOException {
        FastScanner sc = new FastScanner();
        int N = sc.nextInt();
        int M = sc.nextInt();

        if (M == 0) {
            StringBuilder sb = new StringBuilder();
            for (int i = 1; i <= N; i++) {
                if (i > 1) sb.append(' ');
                sb.append(1);
            }
            System.out.println(sb.toString());
            return;
        }

        int D = 2 * M;
        int[] rev = new int[D];
        long[] keys = new long[D];
        final int MASK20 = (1 << 20) - 1;

        for (int i = 0; i < M; i++) {
            int u = sc.nextInt();
            int v = sc.nextInt();

            int id1 = 2 * i;
            int id2 = 2 * i + 1;

            rev[id1] = id2;
            rev[id2] = id1;

            keys[id1] = ((long) u << 40) | ((long) v << 20) | id1;
            keys[id2] = ((long) v << 40) | ((long) u << 20) | id2;
        }

        Arrays.sort(keys);

        int[] sortedTarget = new int[D];
        int[] sortedDir = new int[D];
        int[] start = new int[N + 2];
        int[] end = new int[N + 2];
        Arrays.fill(start, -1);

        for (int pos = 0; pos < D; pos++) {
            long key = keys[pos];
            int src = (int) (key >>> 40);
            int tgt = (int) ((key >>> 20) & MASK20);
            int id = (int) (key & MASK20);

            sortedTarget[pos] = tgt;
            sortedDir[pos] = id;

            if (start[src] == -1) start[src] = pos;
            end[src] = pos + 1;
        }

        keys = null;

        int[] val = new int[D];
        int[] best = new int[N + 1];

        for (int v = N; v >= 1; v--) {
            int L = start[v];
            if (L == -1) continue;
            int R = end[v];

            for (int pos = L; pos < R; pos++) {
                int u = sortedTarget[pos];
                if (u < v) {
                    int id = sortedDir[pos];
                    val[id] = 1 + best[u];
                }
            }

            int suffix = 0;
            for (int pos = R - 1; pos >= L; pos--) {
                int u = sortedTarget[pos];
                int idVtoU = sortedDir[pos];

                if (u < v) {
                    int revId = rev[idVtoU];
                    val[revId] = 1 + suffix;
                }

                int valHere = val[idVtoU];
                if (valHere > suffix) suffix = valHere;
            }

            for (int pos = L; pos < R; pos++) {
                int u = sortedTarget[pos];
                int idVtoU = sortedDir[pos];
                int revId = rev[idVtoU];
                int valUV = val[revId];

                if (valUV > best[u]) best[u] = valUV;
            }
        }

        StringBuilder sb = new StringBuilder();
        for (int s = 1; s <= N; s++) {
            int maxVal = 0;
            int L = start[s];

            if (L != -1) {
                int R = end[s];
                for (int pos = L; pos < R; pos++) {
                    int id = sortedDir[pos];
                    int valHere = val[id];
                    if (valHere > maxVal) maxVal = valHere;
                }
            }

            int ans = 1 + maxVal;
            if (s > 1) sb.append(' ');
            sb.append(ans);
        }

        System.out.println(sb.toString());
    }
}
